  const f = await fixture(mode); await expect(f.executor.execute('run', new AbortController().signal)).rejects.toThrow('CONTAINED_SCOPE_MISMATCH');
  expect(f.calls.some(x => x.endsWith('/start') || x.startsWith('DELETE'))).toBe(false);
